/**
 * @name Subprocess Injection from Library Input
 * @description Detects command injection where the source is a function parameter (library context).
 * @kind path-problem
 * @problem.severity error
 * @id py/subprocess-injection-library
 * @tags security
 *       external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.Concepts

module LibraryInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    sink = any(SystemCommandExecution sce).getCommand()
  }
}

module LibraryInjectionFlow = TaintTracking::Global<LibraryInjectionConfig>;
import LibraryInjectionFlow::PathGraph

from LibraryInjectionFlow::PathNode source, LibraryInjectionFlow::PathNode sink
where LibraryInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential command injection from parameter $@.", source.getNode(), "parameter"
